ListAccounts:
const result = await client.listAccounts();
const policy = result.Accounts.find((account) => account.Email === accountEmail)?.PgpAuthorization;
if (policy?.State === "unavailable") throw new Error("Policy unavailable; stop");
console.log(policy?.RequiredSignatures, policy?.RequiredSignerFingerprints);

ConfigureBankPgpPolicy:
await client.configureBankPgpPolicy("osuuspankki", {
  RequiredSignatureCount: 2,
  RequiredSignerFingerprints: [erpPrimaryFingerprint],
  ExpectedRevision: reviewedRevision,
});
// Omit the signer list to preserve it; [] explicitly clears it for this bank.
// First-time exemptions/shared certificates also require explicit confirmation.

DeletePgpKey:
await client.deletePgpKey({
  Fingerprint: primaryFingerprint,
  ExpectedRevision: reviewedRevision,
});
// A required signer cannot be deleted, and locked accounts refuse all key edits.

RequestActionMfa:
const actionCredential = client.session.accessToken;
if (!actionCredential) throw new Error("Complete Admin login first");
await client.requestActionMfa(actionCredential);
// Collect the new SMS code. This call does not authorize a mutation by itself.

LockPgpPolicy:
// IRREVERSIBLE: review every account key and bank policy first.
const actionCredential = client.session.accessToken;
if (!actionCredential) throw new Error("Complete Admin login first");
await client.lockPgpPolicy({
  ExpectedRevision: reviewedRevision,
  AccessToken: actionCredential,
  MfaType: "SOFTWARE_TOKEN_MFA",
  Code: freshAuthenticatorCode,
});
